import React from "react";

import "../assets/css/loading-page.css";

function LoadingPage(props) {
  const startingPositions = [
    { x: 25, y: 50 },
    { x: 50, y: 25 },
    { x: 0, y: 0 },
    { x: 50, y: 50 }
  ];
  return (
    <div className="loading-page-wrapper">
      <h1 className="loading-text-wrapper montserrat-light">loading</h1>
      {startingPositions.map(position => (
        <div
          className="circle"
          style={{
            offsetPath: `path("M ${position.x}, ${position.y} a 25,25 0 1,1 50,0 a 25,25 0 1,1 -50,0")`
          }}
        ></div>
      ))}
    </div>
  );
}

export default LoadingPage;
